// Return the number of islands: groups of '1' cells connected up, down, left or right. One test is a single
// 100,000-cell island, so avoid deep recursion.
function numIslands(grid: string[][]): number {
  throw new Error('Not implemented');
}

p-number-of-islands.solution:
function numIslands(grid: string[][]): number {
  const rows = grid.length;
  const cols = rows ? grid[0].length : 0;
  const visited = Array.from({ length: rows }, () => new Array<boolean>(cols).fill(false));
  const steps = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let islands = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '1' || visited[r][c]) continue;
      islands++;
      visited[r][c] = true;
      const stack: [number, number][] = [[r, c]];
      while (stack.length > 0) {
        const [y, x] = stack.pop()!;
        for (const [dy, dx] of steps) {
          const ny = y + dy;
          const nx = x + dx;
          if (ny >= 0 && ny < rows && nx >= 0 && nx < cols && grid[ny][nx] === '1' && !visited[ny][nx]) {
            visited[ny][nx] = true;
            stack.push([ny, nx]);
          }
        }
      }
    }
  }
  return islands;
}

