  orderSteps(steps, [['parse', 'fetch'], ['embed', 'parse'], ['index', 'embed'], ['notify', 'index']]),
  ['fetch', 'parse', 'embed', 'index', 'notify'],
);
// Listed order is not dependency order: notify is listed first but runs last.
