p-climbing-stairs.solution:
function climbStairs(n: number): number {
  let oneBack = 1; // ways to reach step 0
  let twoBack = 0;
  for (let step = 1; step <= n; step++) {
    [oneBack, twoBack] = [oneBack + twoBack, oneBack];
  }
  return oneBack;
}

